xpath.script:
document.addEventListener('DOMContentLoaded', function () {
    var boxes = document.querySelectorAll('.uellow-sel-line');
    var gos = document.querySelectorAll('.uellow-sel-go');
    if (!boxes.length || !gos.length) { return; }
    function refresh() {
        var c = document.querySelectorAll('.uellow-sel-line:checked');
        var partial = c.length && c.length < boxes.length;
        gos.forEach(function (g) {
            g.style.display = partial ? '' : 'none';
            var n = g.querySelector('.uellow-sel-n');
            if (n) { n.textContent = c.length; }
        });
    }
    boxes.forEach(function (b) {
        b.addEventListener('change', refresh);
    });
    gos.forEach(function (g) {
        g.addEventListener('click', function () {
            var f = document.createElement('form');
            f.method = 'POST';
            f.action = '/shop/cart/checkout-selected';
            var t = document.createElement('input');
            t.type = 'hidden'; t.name = 'csrf_token';
            t.value = (window.odoo && odoo.csrf_token) || '';
            f.appendChild(t);
            document.querySelectorAll('.uellow-sel-line:checked')
                .forEach(function (b) {
                    var i = document.createElement('input');
                    i.type = 'hidden'; i.name = 'line_ids';
                    i.value = b.dataset.lineId;
                    f.appendChild(i);
                });
            document.body.appendChild(f);
            f.submit();
        });
    });
});

document.addEventListener('DOMContentLoaded', function () {
    var boxes = document.querySelectorAll('.uellow-sel-line');
    var wrap = document.getElementById('uellow_selective_checkout');
    var inputs = document.getElementById('uellow_sel_inputs');
    var count = document.getElementById('uellow_sel_count');
    if (!boxes.length || !wrap) { return; }
    function refresh() {
        var checked = document.querySelectorAll('.uellow-sel-line:checked');
        inputs.innerHTML = '';
        checked.forEach(function (b) {
            var i = document.createElement('input');
            i.type = 'hidden'; i.name = 'line_ids';
            i.value = b.dataset.lineId;
            inputs.appendChild(i);
        });
        count.textContent = checked.length;
        // Show the button only for a PARTIAL selection —
        // all/none selected = the normal checkout button.
        wrap.style.display =
            (checked.length && checked.length < boxes.length)
                ? '' : 'none';
    }
    boxes.forEach(function (b) {
        b.addEventListener('change', refresh);
    });
});
